import{_ as a,o as i,c as t,ai as r}from"./chunks/framework.ETupdKIa.js";const y=JSON.parse('{"title":"Arrays asList()について","description":"","frontmatter":{"title":"Arrays asList()について","date":"2026-02-25T00:00:00.000Z","status":"draft"},"headers":[],"relativePath":"til/Java/20260225_Arrays asList()について.md","filePath":"til/Java/20260225_Arrays asList()について.md"}'),e={name:"til/Java/20260225_Arrays asList()について.md"};function l(p,s,h,n,k,d){return i(),t("div",null,[...s[0]||(s[0]=[r('<h1 id="_20260225-【wip】arrays-aslist-について" tabindex="-1">20260225_【WIP】Arrays.asList()について <a class="header-anchor" href="#_20260225-【wip】arrays-aslist-について" aria-label="Permalink to “20260225_【WIP】Arrays.asList()について”">​</a></h1><p>Arrays.asList()は配列をList型に変換できるが、引数の型に注意する必要がある。</p><p>引数が参照型配列の場合は、配列の各要素がそのままListの要素となり、想定通りの結果となる。</p><p>引数がプリミティブ型配列の場合は、配列そのものが要素して扱われ、要素数1のListとなり、直感に反する。</p><p>これは、Arrays.asList()の定義を見ると、理由がわかる。</p><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">T</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Arrays.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">asList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(T… a)</span></span></code></pre></div><p>Tは参照型のオブジェクトのみ許容し、プリミティブ型は許容しない。参照型配列の場合は、それそのものが可変長引数aとして扱われる（「T… a」は内部的には「T[] a」である）。プリミティブ型配列が渡された場合、プリミティブ型自体はTに当てはまることができないので、プリミティブ型配列そのものをTとして扱われることになる。</p>',7)])])}const o=a(e,[["render",l]]);export{y as __pageData,o as default};
